export const FOUNDATIONS_BEHAVIORAL_QUIZZES = [
  {
    id:`fb01`, cat:`Behavioral & Social Sciences`, title:`Intro to Psychology: What Is Psychology?`, diff:`Easy`,
    qs:[
      { q:`What is psychology, broadly defined?`, ch:[`The study of ancient civilizations`,`The scientific study of the mind and behavior`,`The study of chemical reactions in living organisms`,`The study of Earth's physical structure`], ans:1, exp:`Psychology is the scientific study of mental processes (thoughts, feelings, perceptions) and behavior, in both individuals and groups.` },
      { q:`Why is psychology considered a science rather than just informal opinion or philosophy?`, ch:[`It relies on systematic observation, experimentation, and evidence to test ideas about mind and behavior`,`Psychology doesn't actually use any research methods`,`Psychology is purely a matter of personal opinion`,`Psychology never uses data of any kind`], ans:0, exp:`Psychology uses the scientific method — forming testable hypotheses, gathering data through observation and experiments, and drawing evidence-based conclusions — which sets it apart from pure speculation.` },
      { q:`What is the difference between a clinical psychologist and a psychiatrist?`, ch:[`They are exactly the same profession`,`A psychiatrist is a medical doctor who can prescribe medication; a clinical psychologist typically cannot`,`A clinical psychologist always outranks a psychiatrist`,`Psychiatrists never provide therapy`], ans:1, exp:`Psychiatrists attend medical school and can prescribe medication, while clinical psychologists typically hold a doctoral degree in psychology and focus on therapy and assessment, generally without prescribing rights.` },
      { q:`What does "behavior" refer to in the context of psychology?`, ch:[`Only unconscious thoughts`,`Any observable action or response of an organism`,`Only a person's stated opinions`,`A term with no clear definition in psychology`], ans:1, exp:`Behavior refers to any observable action — from a simple reflex to complex social interaction — that psychologists can study, measure, and analyze.` },
      { q:`Why might someone interested in a health career benefit from studying basic psychology?`, ch:[`Psychology has no relevance to healthcare`,`Understanding how people think, feel, and behave helps in communicating with and caring for patients effectively`,`Psychology only applies to mental health specialists`,`Psychology replaces the need for studying biology`], ans:1, exp:`Nearly every healthcare role involves communicating with patients, understanding their behavior and emotional state, and adapting care accordingly — foundational psychology knowledge supports all of that.` },
    ],
  },
  {
    id:`fb02`, cat:`Behavioral & Social Sciences`, title:`Memory Basics`, diff:`Easy`,
    qs:[
      { q:`What are the three main stages of memory processing?`, ch:[`Encoding, storage, and retrieval`,`Thinking, feeling, and acting`,`Input, output, and feedback`,`Sensation, perception, and reaction`], ans:0, exp:`Memory involves encoding (getting information in), storage (keeping it over time), and retrieval (accessing it later when needed).` },
      { q:`What is the difference between short-term and long-term memory?`, ch:[`They are identical concepts`,`Short-term memory holds a small amount of information briefly; long-term memory can store much more information for extended periods`,`Long-term memory only lasts a few seconds`,`Short-term memory has unlimited capacity`], ans:1, exp:`Short-term memory holds a limited amount of information for a short time (often less than a minute without rehearsal), while long-term memory can retain much larger amounts of information for days, years, or a lifetime.` },
      { q:`What is "rehearsal," in the context of memory?`, ch:[`Practicing a physical skill only`,`Repeating information to help move it from short-term to long-term memory`,`A type of forgetting`,`A term unrelated to memory`], ans:1, exp:`Rehearsal — repeating information, either by rote or through more meaningful review — helps transfer it from short-term to more durable long-term memory storage.` },
      { q:`Why does spacing out study sessions over several days tend to improve long-term retention compared to cramming?`, ch:[`Spaced practice gives the brain repeated opportunities to retrieve and reinforce information over time, strengthening memory`,`Cramming and spaced practice produce identical retention`,`Spacing out study sessions has no effect on memory`,`Cramming is always more effective for long-term retention`], ans:0, exp:`This "spacing effect" is one of the most well-supported findings in memory research — revisiting material after a delay forces active retrieval, which strengthens long-term retention far more than massed, last-minute cramming.` },
      { q:`What is a mnemonic device?`, ch:[`A medical instrument`,`A memory technique, like an acronym or rhyme, that helps make information easier to recall`,`A type of memory disorder`,`A term unrelated to learning`], ans:1, exp:`Mnemonic devices are memory aids — acronyms, rhymes, or vivid associations — that organize information in a way that's easier for the brain to encode and later retrieve.` },
    ],
  },
  {
    id:`fb03`, cat:`Behavioral & Social Sciences`, title:`Learning: Classical & Operant Conditioning`, diff:`Medium`,
    qs:[
      { q:`What is classical conditioning?`, ch:[`Learning that occurs when a neutral stimulus becomes associated with a stimulus that already triggers a response`,`Learning that only happens through rewards and punishments`,`A type of memory loss`,`A term unrelated to learning`], ans:0, exp:`Classical conditioning, famously studied by Ivan Pavlov, occurs when a previously neutral stimulus (like a bell) becomes associated with a stimulus that naturally triggers a response (like food triggering salivation), until the neutral stimulus alone triggers that response.` },
      { q:`In Pavlov's classic experiment, what did the dogs eventually learn to salivate in response to, after conditioning?`, ch:[`A bell, after it was repeatedly paired with food`,`A completely unrelated color`,`Nothing new — their behavior never changed`,`Only the sight of food, unchanged from before`], ans:0, exp:`After the bell was repeatedly paired with the presentation of food, dogs began salivating at the sound of the bell alone — a learned (conditioned) response to a previously neutral stimulus.` },
      { q:`What is operant conditioning?`, ch:[`Learning based on associating two stimuli together`,`Learning through the consequences of behavior — reinforcement makes a behavior more likely, punishment makes it less likely`,`A term unrelated to behavior change`,`Learning that only occurs in early childhood`], ans:1, exp:`Operant conditioning, studied extensively by B.F. Skinner, describes how behaviors are shaped by their consequences — reinforced behaviors tend to increase, while punished behaviors tend to decrease.` },
      { q:`What is positive reinforcement?`, ch:[`Adding an unpleasant consequence to decrease a behavior`,`Adding a desirable consequence after a behavior, to increase the likelihood that behavior happens again`,`Removing something pleasant to decrease a behavior`,`A term unrelated to operant conditioning`], ans:1, exp:`Positive reinforcement involves adding something desirable (like praise or a reward) after a behavior, which increases the likelihood that behavior will be repeated.` },
      { q:`How does negative reinforcement differ from punishment?`, ch:[`They are the exact same thing`,`Negative reinforcement removes something unpleasant to increase a behavior; punishment adds or removes something to decrease a behavior`,`Negative reinforcement always decreases behavior, just like punishment`,`Punishment always increases the likelihood of a behavior`], ans:1, exp:`Negative reinforcement strengthens a behavior by removing an unpleasant stimulus (like turning off an annoying alarm by getting out of bed), while punishment weakens a behavior by adding an unpleasant consequence or removing something desirable.` },
    ],
  },
  {
    id:`fb04`, cat:`Behavioral & Social Sciences`, title:`Motivation & Emotion Basics`, diff:`Medium`,
    qs:[
      { q:`What is the difference between intrinsic and extrinsic motivation?`, ch:[`Intrinsic motivation comes from internal satisfaction or interest; extrinsic motivation comes from external rewards or pressures`,`They are identical concepts`,`Extrinsic motivation always produces better long-term results than intrinsic motivation`,`Intrinsic motivation only applies to young children`], ans:0, exp:`Intrinsic motivation is doing something because it's personally interesting or satisfying (like studying biology out of curiosity), while extrinsic motivation is doing something for an external reward or to avoid a consequence (like studying only to get a good grade).` },
      { q:`What is Maslow's hierarchy of needs generally used to illustrate?`, ch:[`That all human needs are equally urgent at all times`,`A ranked model suggesting basic needs (like food and safety) generally must be met before higher-level needs (like self-actualization) become primary motivators`,`That psychological needs don't exist`,`A model exclusively about physical health, unrelated to motivation`], ans:1, exp:`Maslow's hierarchy proposes that people are generally motivated to satisfy more basic needs (physiological, safety) before they're strongly motivated to pursue higher-level needs like belonging, esteem, and self-actualization.` },
      { q:`What are the basic components most psychologists agree make up an emotion?`, ch:[`A physiological response, a subjective feeling, and often an expressive/behavioral component`,`Only a conscious thought, with no physical component`,`Emotions have no measurable components at all`,`Only external behavior, with no internal experience`], ans:0, exp:`Emotions typically involve a physiological response (like a racing heart), a subjective felt experience, and an expressive or behavioral component (like a facial expression or action tendency).` },
      { q:`What is the James-Lange theory of emotion, in simple terms?`, ch:[`Emotions cause physiological responses, not the other way around`,`Physiological responses to a stimulus occur first, and the brain's interpretation of that bodily response produces the felt emotion`,`Emotions and physiological responses are entirely unrelated`,`This theory claims emotions are purely learned, with no biological basis`], ans:1, exp:`The James-Lange theory proposes that we first experience a physiological reaction to a stimulus (like a racing heart when startled), and the brain then interprets that bodily reaction as a specific emotion (like fear).` },
      { q:`Why might understanding your own motivation help with long-term goals, like studying for a challenging class?`, ch:[`Motivation has no bearing on whether goals are achieved`,`Recognizing what genuinely motivates you (interest, values, rewards) can help you build habits and strategies that sustain effort over time`,`External rewards are the only thing that ever motivates people`,`Understanding motivation guarantees success with no additional effort needed`], ans:1, exp:`Understanding what drives you — whether it's curiosity, long-term goals, or external accountability — can help you design study habits and environments that actually sustain your effort, rather than relying on willpower alone.` },
    ],
  },
  {
    id:`fb05`, cat:`Behavioral & Social Sciences`, title:`Stress & Coping 101`, diff:`Easy`,
    qs:[
      { q:`What is stress, in a psychological sense?`, ch:[`A purely physical illness unrelated to the mind`,`The body and mind's response to a perceived challenge or threat`,`A permanent personality trait`,`A term with no real scientific meaning`], ans:1, exp:`Stress is the psychological and physiological response that occurs when we perceive a situation as challenging, threatening, or beyond our current ability to cope.` },
      { q:`What is the "fight or flight" response?`, ch:[`A slow, gradual physical change with no connection to stress`,`A rapid physiological response to a perceived threat, preparing the body to confront or flee danger`,`A response that only occurs during sleep`,`A term unrelated to the nervous system`], ans:1, exp:`The fight-or-flight response is a rapid, automatic physiological reaction (increased heart rate, adrenaline release) triggered by a perceived threat, preparing the body to either confront or escape it.` },
      { q:`What's the difference between acute stress and chronic stress?`, ch:[`Acute stress is short-term and often related to a specific event; chronic stress is prolonged, ongoing stress`,`They are identical in duration and effect`,`Chronic stress only lasts a few seconds`,`Acute stress always causes more long-term health problems than chronic stress`], ans:0, exp:`Acute stress is a short-term response to a specific, often immediate situation (like a test), while chronic stress persists over weeks, months, or longer, and is associated with more significant long-term health effects.` },
      { q:`Which of these is generally considered a healthy coping strategy for managing stress?`, ch:[`Completely avoiding the stressor and all related tasks indefinitely`,`Regular exercise, adequate sleep, and talking to someone you trust`,`Ignoring the problem and hoping it resolves itself with no action`,`Increasing caffeine intake as the sole strategy`], ans:1, exp:`Exercise, sufficient sleep, and social support are all well-supported strategies for managing stress in a healthy, sustainable way, unlike avoidance-based coping, which tends to worsen stress over time.` },
      { q:`Why is some level of stress considered normal, or even helpful, rather than something to eliminate entirely?`, ch:[`All stress is harmful with no exceptions`,`Moderate stress can improve focus and performance on challenging tasks, up to a point, before it becomes overwhelming`,`Stress has no effect on performance either way`,`Stress should always be avoided completely for optimal performance`], ans:1, exp:`Research on stress and performance (sometimes called the Yerkes-Dodson law) suggests moderate stress can actually sharpen focus and motivation, though performance tends to decline again once stress becomes excessive.` },
    ],
  },
  {
    id:`fb06`, cat:`Behavioral & Social Sciences`, title:`Social Psychology: Conformity & Group Behavior`, diff:`Medium`,
    qs:[
      { q:`What is conformity, in a social psychology sense?`, ch:[`Refusing to change any behavior regardless of social pressure`,`Adjusting one's behavior or beliefs to match those of a group`,`A term unrelated to group dynamics`,`Only occurring in formal, organized settings like a classroom`], ans:1, exp:`Conformity is the tendency to adjust one's own behavior, attitudes, or beliefs to align with those of a group, often due to social pressure — whether that pressure is explicit or simply implied.` },
      { q:`What did Solomon Asch's famous line-length experiments demonstrate about conformity?`, ch:[`People never conform to obviously incorrect group answers`,`A significant number of people will give an obviously incorrect answer just to match a unanimous group, even without direct pressure`,`Group pressure has no measurable effect on individual judgment`,`Conformity only happens when a reward is directly offered`], ans:1, exp:`In Asch's experiments, many participants gave an answer they could clearly see was wrong, simply to match the unanimous (and incorrect) answers given by other group members — a striking demonstration of conformity pressure.` },
      { q:`What is "groupthink"?`, ch:[`A decision-making process that always leads to the best possible outcome`,`A pattern where a group's desire for harmony or conformity leads to poor decision-making by suppressing dissenting opinions`,`A term unrelated to group dynamics`,`Only a positive phenomenon with no downsides`], ans:1, exp:`Groupthink occurs when a group's desire to maintain consensus and avoid conflict overrides realistic evaluation of alternatives, often leading to flawed decisions because dissenting views are suppressed or not voiced.` },
      { q:`What is the bystander effect?`, ch:[`People are more likely to help someone in need when more bystanders are present`,`Individuals are less likely to help someone in need when more other people are present, partly due to diffusion of responsibility`,`A term unrelated to helping behavior`,`Bystanders always intervene immediately in emergencies`], ans:1, exp:`The bystander effect describes the finding that the presence of more onlookers actually decreases the likelihood that any individual will help in an emergency, partly because responsibility feels diffused across the group.` },
      { q:`What is social facilitation?`, ch:[`The tendency to always perform worse on any task when others are watching`,`The tendency to perform better on simple, well-practiced tasks when others are present, but sometimes worse on complex or unfamiliar tasks`,`A term unrelated to performance`,`A phenomenon that only affects children`], ans:1, exp:`Social facilitation refers to how the presence of others can boost performance on tasks a person is already skilled at, while potentially hurting performance on unfamiliar or difficult tasks due to increased arousal and self-consciousness.` },
    ],
  },
  {
    id:`fb07`, cat:`Behavioral & Social Sciences`, title:`Personality Basics`, diff:`Medium`,
    qs:[
      { q:`What is personality, in a psychological sense?`, ch:[`A person's relatively stable and consistent patterns of thoughts, feelings, and behaviors over time`,`A trait that changes completely every day`,`A term with no consistent scientific definition`,`Only how a person looks physically`], ans:0, exp:`Personality refers to the enduring, characteristic patterns of thinking, feeling, and behaving that distinguish one individual from another, and that tend to remain relatively stable across situations and time.` },
      { q:`What are the "Big Five" personality traits commonly studied by psychologists?`, ch:[`Openness, conscientiousness, extraversion, agreeableness, and neuroticism`,`Happy, sad, angry, surprised, and disgusted`,`Intelligence, height, weight, age, and gender`,`A term unrelated to any real research model`], ans:0, exp:`The Big Five (sometimes remembered with the acronym OCEAN) — openness, conscientiousness, extraversion, agreeableness, and neuroticism — is one of the most widely used and researched models of personality traits.` },
      { q:`What does high "conscientiousness" in the Big Five model typically describe?`, ch:[`A tendency to be disorganized and impulsive`,`A tendency to be organized, dependable, and goal-directed`,`A tendency to be highly emotional and anxious`,`A tendency to avoid all social interaction`], ans:1, exp:`Conscientiousness describes a tendency toward being organized, disciplined, dependable, and oriented toward achieving goals — often linked to strong academic and career performance.` },
      { q:`Is personality generally considered fixed from birth, or shaped by both genetics and environment?`, ch:[`Personality is entirely determined by genetics alone, with zero environmental influence`,`Most psychologists view personality as shaped by an interaction of genetic predispositions and life experiences/environment`,`Personality is entirely random with no underlying influences`,`Personality is determined solely by environment, with zero genetic influence`], ans:1, exp:`Most current research suggests personality develops through an interaction between genetic predispositions (temperament) and environmental influences (upbringing, culture, experiences) — not purely one or the other.` },
      { q:`Why might understanding personality traits (like your own conscientiousness or extraversion) be useful when choosing study habits?`, ch:[`Personality has no relevance to how someone studies`,`Recognizing your own tendencies can help you choose strategies that fit how you naturally work best, such as structured schedules or group study`,`Everyone should use the exact same study method regardless of personality`,`Personality traits cannot be recognized or described in any useful way`], ans:1, exp:`Someone with high conscientiousness might thrive with a structured study schedule, while a more extraverted student might benefit from group study sessions — understanding your own tendencies can help you build habits that actually stick.` },
    ],
  },
  {
    id:`fb08`, cat:`Behavioral & Social Sciences`, title:`Developmental Psychology Basics`, diff:`Medium`,
    qs:[
      { q:`What does developmental psychology study?`, ch:[`Only the psychology of infants`,`How people grow and change physically, cognitively, and socially across their entire lifespan`,`Only aging and memory loss in older adults`,`A field unrelated to any age-related change`], ans:1, exp:`Developmental psychology examines how humans change and develop across the entire lifespan — from infancy through childhood, adolescence, adulthood, and old age.` },
      { q:`What did Jean Piaget's theory of cognitive development propose?`, ch:[`Children think about the world in exactly the same way as adults`,`Children move through distinct stages of cognitive development, each with qualitatively different ways of understanding the world`,`Cognitive development stops entirely after infancy`,`Piaget's theory is unrelated to how children think`], ans:1, exp:`Piaget proposed that children progress through a series of qualitatively distinct stages of cognitive development (sensorimotor, preoperational, concrete operational, formal operational), each reflecting a different way of understanding and reasoning about the world.` },
      { q:`What is "attachment," in developmental psychology?`, ch:[`A term unrelated to early childhood`,`The deep emotional bond that typically forms between an infant and their primary caregiver(s)`,`A term describing only romantic relationships`,`A type of memory disorder`], ans:1, exp:`Attachment refers to the emotional bond that develops between an infant and their primary caregiver, which research suggests plays an important role in shaping later social and emotional development.` },
      { q:`According to Erik Erikson's theory, what is a central psychological task typically associated with adolescence?`, ch:[`Developing a sense of trust versus mistrust, as in infancy`,`Developing a stable sense of identity versus experiencing role confusion`,`Achieving generativity versus stagnation, as in mid-adulthood`,`Resolving integrity versus despair, as in late life`], ans:1, exp:`Erikson's stage theory identifies "identity versus role confusion" as the central developmental task of adolescence, as teens explore and try to form a coherent sense of who they are.` },
      { q:`Why is the "nature vs. nurture" debate relevant to developmental psychology?`, ch:[`It has no relevance to development at all`,`It examines how much of development is driven by genetics (nature) versus environment and experience (nurture)`,`It only applies to physical, not psychological, development`,`It was fully resolved decades ago in favor of nature alone`], ans:1, exp:`The nature-nurture debate explores the relative contributions of genetics and environment to development, and most modern developmental psychologists view the two as constantly interacting rather than one simply "winning" over the other.` },
    ],
  },
  {
    id:`fb09`, cat:`Behavioral & Social Sciences`, title:`Sociology 101: Culture & Society`, diff:`Easy`,
    qs:[
      { q:`What does sociology study?`, ch:[`Individual brain chemistry`,`Human society, social relationships, and the institutions that shape group behavior`,`Only the behavior of animals`,`A field unrelated to human behavior`], ans:1, exp:`Sociology examines how societies are organized, how social relationships and institutions (like family, education, and religion) function, and how they shape human behavior at a group level.` },
      { q:`What is "culture," in a sociological sense?`, ch:[`Only fine art and music`,`The shared beliefs, values, customs, and practices of a group of people`,`A term unrelated to any group behavior`,`Only a country's official laws`], ans:1, exp:`Culture encompasses the shared beliefs, values, norms, customs, language, and practices that characterize a particular group or society, passed down and shared among its members.` },
      { q:`What is a "social norm"?`, ch:[`A law enforced strictly by the government`,`An unwritten, generally shared expectation about how people should behave in a given society or situation`,`A term unrelated to social behavior`,`Something that never varies across cultures`], ans:1, exp:`Social norms are the (often unwritten) shared rules and expectations for behavior within a group or society — like standing in line or shaking hands — and they can vary significantly across cultures.` },
      { q:`What is socialization?`, ch:[`A medical procedure`,`The lifelong process through which individuals learn and internalize the norms, values, and behaviors of their culture`,`A term describing only childhood friendships`,`A process that occurs only once, in infancy`], ans:1, exp:`Socialization is the ongoing process by which individuals learn the norms, values, and expected behaviors of their culture — starting in early childhood but continuing throughout life via family, school, peers, and other institutions.` },
      { q:`Why is understanding cultural differences valuable in a healthcare setting?`, ch:[`It has no practical value in healthcare`,`Patients' cultural backgrounds can shape their health beliefs, communication styles, and expectations, so cultural awareness improves care`,`All patients share identical cultural expectations, so this isn't relevant`,`Cultural awareness only matters for social workers, never for clinicians`], ans:1, exp:`Patients bring different beliefs about health, illness, family involvement, and communication shaped by their cultural background — understanding this helps healthcare providers communicate more effectively and deliver more respectful, effective care.` },
    ],
  },
  {
    id:`fb10`, cat:`Behavioral & Social Sciences`, title:`Research Methods Basics`, diff:`Medium`,
    qs:[
      { q:`What is the main advantage of an experiment over a purely observational (correlational) study?`, ch:[`Experiments cannot establish cause-and-effect relationships`,`A well-designed experiment, with manipulated variables and random assignment, can help establish cause-and-effect relationships`,`Observational studies are always more scientifically rigorous`,`There is no meaningful difference between the two approaches`], ans:1, exp:`By manipulating an independent variable and randomly assigning participants to conditions, experiments can help isolate cause-and-effect relationships in a way that purely observational, correlational studies cannot.` },
      { q:`What does it mean when two variables are "correlated"?`, ch:[`One variable definitely causes changes in the other`,`The variables tend to change together in a predictable way, but this alone doesn't prove that one causes the other`,`The variables have no relationship whatsoever`,`Correlation always implies direct causation`], ans:1, exp:`Correlation means two variables tend to change together (positively or negatively), but a correlation alone cannot prove that one variable causes changes in the other — there could be a third factor, or the relationship could run in either direction.` },
      { q:`Why is a control group important in an experiment?`, ch:[`It has no important role in the study`,`It provides a baseline for comparison, helping researchers determine whether the treatment/manipulation actually caused an effect`,`Control groups always receive the experimental treatment`,`Control groups make an experiment less scientifically valid`], ans:1, exp:`A control group doesn't receive the experimental treatment, giving researchers a baseline to compare against the experimental group, so any difference can more confidently be attributed to the treatment itself.` },
      { q:`What is informed consent, in the context of research involving human participants?`, ch:[`A rule that only applies to medical research, never psychological research`,`The requirement that participants understand what a study involves and voluntarily agree to participate before it begins`,`A term unrelated to research ethics`,`A form signed only after a study has already concluded`], ans:1, exp:`Informed consent requires that research participants be told what the study involves (as much as ethically possible) and voluntarily agree to take part before participating, protecting their autonomy and well-being.` },
      { q:`Why do researchers use random assignment when placing participants into experimental groups?`, ch:[`Random assignment has no scientific benefit`,`It helps ensure that pre-existing differences between participants are spread evenly across groups, so differences in outcomes are more likely due to the treatment itself`,`Random assignment guarantees a study will have no errors at all`,`Random assignment is only used in surveys, never experiments`], ans:1, exp:`Random assignment helps distribute participant characteristics (age, background, ability, etc.) roughly evenly across groups, reducing the chance that pre-existing differences — rather than the treatment itself — explain any observed effect.` },
    ],
  },
  {
    id:`fb11`, cat:`Behavioral & Social Sciences`, title:`Nature vs. Nurture`, diff:`Medium`,
    qs:[
      { q:`What does the "nature vs. nurture" debate examine?`, ch:[`Whether people prefer indoor or outdoor activities`,`The relative contributions of genetics (nature) and environment/experience (nurture) to human development and traits`,`A debate with no scientific relevance today`,`Whether personality is entirely determined by upbringing alone`], ans:1, exp:`This long-running debate in psychology examines how much of a given trait or behavior is shaped by inherited genetics versus environmental factors like upbringing, culture, and experience.` },
      { q:`What do twin studies help researchers investigate regarding nature vs. nurture?`, ch:[`Nothing useful — twin studies have no scientific value`,`By comparing identical twins (who share all genes) to fraternal twins (who share about half), researchers can estimate the relative influence of genetics versus environment on a trait`,`Twin studies only apply to physical traits, never psychological ones`,`Twin studies prove that environment has zero influence on any trait`], ans:1, exp:`Because identical twins share 100% of their genes while fraternal twins share about 50% (like typical siblings), comparing how similar twins are on a trait helps researchers estimate how much of that trait's variation is linked to genetics versus environment.` },
      { q:`What is the current scientific consensus on most complex human traits, like intelligence or personality?`, ch:[`They are determined entirely by genetics with zero environmental influence`,`Most complex traits arise from an interaction between genetic predispositions and environmental influences, not one factor alone`,`They are determined entirely by environment with zero genetic influence`,`Nature and nurture have been proven to have no relationship to each other at all`], ans:1, exp:`Most researchers today agree that complex traits result from a continuous interplay between genes and environment, rather than either factor acting in isolation — this is sometimes summarized as "nature via nurture."` },
      { q:`What is an example of how environment ("nurture") can influence how a genetic predisposition ("nature") is expressed?`, ch:[`Genetics always express identically regardless of environment`,`A child with a genetic predisposition toward high intelligence may only reach their potential with access to good nutrition, education, and stimulation`,`Environment can never affect how genes are expressed`,`Genetic predispositions guarantee a specific outcome no matter the circumstances`], ans:1, exp:`Genetic potential often requires a supportive environment to be fully realized — for example, a child with genes associated with high cognitive potential may not reach that potential without adequate nutrition, education, and stimulation.` },
      { q:`Why is "nature vs. nurture" often considered a misleading way to frame the debate today?`, ch:[`Because it implies an either/or framing, when most traits actually result from a complex interaction between the two, not one versus the other`,`Because nature and nurture have both been fully disproven as factors`,`Because the debate has no remaining relevance to psychology`,`Because this framing accurately captures how traits develop, with no nuance needed`], ans:0, exp:`Framing it as "versus" implies these are competing, separable forces, when in reality most traits emerge from a complex, ongoing interaction between genetics and environment throughout development.` },
    ],
  },
  {
    id:`fb12`, cat:`Behavioral & Social Sciences`, title:`Mental Health Awareness 101`, diff:`Medium`,
    qs:[
      { q:`What is mental health, broadly defined?`, ch:[`The complete absence of any negative emotion`,`A state of psychological well-being that includes how a person thinks, feels, and copes with life's challenges`,`A term that only applies to diagnosed mental illness`,`A fixed trait that never changes throughout life`], ans:1, exp:`Mental health refers to overall psychological well-being — how a person thinks, feels, manages stress, relates to others, and makes decisions — and it exists on a spectrum, not just as the presence or absence of a diagnosed disorder.` },
      { q:`Why is it inaccurate to say someone either "has" or "doesn't have" mental health?`, ch:[`Mental health should be thought of as a spectrum that everyone experiences, with ups and downs, rather than a simple yes/no category`,`Mental health only applies to people diagnosed with a disorder`,`Mental health is entirely unrelated to everyday well-being`,`Everyone's mental health is always identical and unchanging`], ans:0, exp:`Just like physical health, mental health exists on a continuum that fluctuates over time and circumstances — everyone has mental health, and it can be better or worse at different points, not just present or absent.` },
      { q:`What is stigma, in the context of mental health?`, ch:[`A medical treatment for anxiety`,`Negative attitudes, stereotypes, or discrimination toward people experiencing mental health challenges`,`A term unrelated to mental health`,`A type of therapy technique`], ans:1, exp:`Stigma refers to negative societal attitudes or stereotypes about mental health conditions, which can discourage people from seeking help and contribute to feelings of shame or isolation.` },
      { q:`Why might it be helpful for a student to know the signs that a friend may be struggling with their mental health?`, ch:[`It has no practical value for a peer to notice these signs`,`Recognizing changes like withdrawal, mood shifts, or declining performance can help a student support a friend or connect them to appropriate resources`,`Only licensed professionals are ever able to notice these signs`,`Friends should never mention noticing a change in someone's behavior`], ans:1, exp:`Peers are often among the first to notice changes in a friend's behavior, mood, or habits — knowing the general warning signs can help a student offer support or encourage a friend to connect with a counselor or trusted adult.` },
      { q:`What is a healthy first step if a student is feeling persistently overwhelmed, anxious, or down?`, ch:[`Ignoring the feelings entirely and hoping they resolve on their own`,`Talking to a trusted adult, school counselor, or mental health professional about what they're experiencing`,`Avoiding all schoolwork and social contact indefinitely`,`Assuming nothing can help and giving up on seeking support`], ans:1, exp:`Reaching out to a trusted adult, school counselor, or mental health professional is a healthy, proactive first step — these challenges are common, and support and effective strategies (or treatment, if needed) are available.` },
    ],
  },
  {
    id:`fb13`, cat:`Behavioral & Social Sciences`, title:`Sleep Science Basics`, diff:`Easy`,
    qs:[
      { q:`Roughly how many hours of sleep do most teenagers need per night for optimal functioning?`, ch:[`4-5 hours`,`8-10 hours`,`12-14 hours`,`Teens need no more sleep than adults`], ans:1, exp:`Most sleep experts recommend that teenagers get about 8 to 10 hours of sleep per night — more than adults typically need — to support the significant physical and cognitive development happening during adolescence.` },
      { q:`What are the two main types of sleep the brain cycles through each night?`, ch:[`REM sleep and non-REM sleep`,`Deep sleep and awake sleep`,`Morning sleep and evening sleep`,`Fast sleep and slow sleep`], ans:0, exp:`Sleep alternates between REM (rapid eye movement) sleep, associated with vivid dreaming and memory consolidation, and several stages of non-REM sleep, including deep, restorative slow-wave sleep.` },
      { q:`Why is sleep considered important for learning and memory?`, ch:[`Sleep has no effect on memory or learning`,`During sleep, the brain consolidates and strengthens memories formed during the day`,`Sleep actually erases most memories formed that day`,`Only naps help memory, never nighttime sleep`], ans:1, exp:`Research shows the brain processes and consolidates new memories during sleep, which is one reason chronic sleep deprivation is linked to poorer learning, memory, and academic performance.` },
      { q:`What effect does exposure to bright screens (like a phone) right before bed tend to have on sleep?`, ch:[`It has no effect on sleep at all`,`It can suppress melatonin production and delay the onset of sleep`,`It always improves the depth and quality of sleep`,`It only affects sleep in adults, not teens`], ans:1, exp:`Blue light from screens can suppress the release of melatonin (a hormone that promotes sleepiness), which can make it harder to fall asleep and shift the body's natural sleep-wake rhythm later.` },
      { q:`What is "sleep debt"?`, ch:[`A term unrelated to sleep science`,`The cumulative effect of not getting enough sleep over multiple nights, which can impair mood, focus, and health`,`A one-time event with no lasting effects`,`A condition that only affects people who sleep too much`], ans:1, exp:`Sleep debt builds up when someone consistently gets less sleep than their body needs — the effects (impaired focus, mood, immune function) accumulate over time and aren't fully solved by a single night of "catch-up" sleep.` },
    ],
  },
  {
    id:`fb14`, cat:`Behavioral & Social Sciences`, title:`Communication Skills 101`, diff:`Easy`,
    qs:[
      { q:`What is active listening?`, ch:[`Waiting for your turn to speak while thinking about your response`,`Fully focusing on, understanding, and engaging with what someone else is saying before responding`,`Interrupting frequently to share your own opinion`,`A term unrelated to communication`], ans:1, exp:`Active listening means giving the speaker your full attention, seeking to genuinely understand their message, and often reflecting back what you heard, rather than passively waiting to talk.` },
      { q:`What role does nonverbal communication (like body language and tone of voice) play in a conversation?`, ch:[`It has no real impact on how a message is received`,`It significantly shapes how a message is interpreted, often carrying as much or more meaning than the words themselves`,`Only spoken words matter in communication`,`Nonverbal communication only matters in written communication`], ans:1, exp:`Body language, facial expressions, and tone of voice all shape how a listener interprets a message — sometimes conveying more meaning than the literal words, especially when they conflict with what's being said.` },
      { q:`What is "I-statement" communication, often recommended for resolving conflict?`, ch:[`A style that focuses on blaming the other person directly`,`Expressing your own feelings and perspective ("I feel... when...") rather than accusing the other person ("You always...")`,`A style that avoids expressing any feelings at all`,`A communication style unrelated to conflict resolution`], ans:1, exp:`"I-statements" frame a concern around your own feelings and experience ("I feel frustrated when...") rather than an accusatory "you" statement, which tends to reduce defensiveness and keep conversations more productive.` },
      { q:`Why is clarifying or paraphrasing what someone said ("So what I'm hearing is...") a useful communication technique?`, ch:[`It wastes time and adds nothing to a conversation`,`It confirms you understood correctly and shows the speaker you're genuinely engaged`,`It's only useful in formal business settings`,`It should be avoided because it interrupts the speaker`], ans:1, exp:`Paraphrasing back what you heard helps confirm mutual understanding and signals genuine engagement, reducing the chance of miscommunication.` },
      { q:`Why are strong communication skills especially valuable in healthcare careers?`, ch:[`Communication skills have little relevance in clinical settings`,`Clearly explaining information, listening to patient concerns, and coordinating with a care team all depend on effective communication`,`Only written communication matters in healthcare, not spoken`,`Healthcare professionals rarely need to communicate with patients directly`], ans:1, exp:`From explaining a diagnosis clearly to listening carefully to a patient's symptoms and concerns to coordinating with other members of a care team, strong communication is central to virtually every healthcare role.` },
    ],
  },
  {
    id:`fb15`, cat:`Behavioral & Social Sciences`, title:`Time Management for Students`, diff:`Easy`,
    qs:[
      { q:`What is the main benefit of breaking a large assignment into smaller tasks over several days?`, ch:[`It makes the assignment more likely to be forgotten`,`It reduces the feeling of being overwhelmed and makes steady, consistent progress more achievable`,`It has no effect on how manageable a task feels`,`Large assignments should always be done in a single sitting`], ans:1, exp:`Breaking a large project into smaller, specific tasks makes it feel far less overwhelming and allows steady progress over time, rather than a stressful, last-minute rush.` },
      { q:`What is the purpose of prioritizing tasks by both urgency and importance?`, ch:[`To ensure the most time-sensitive and high-value tasks get attention first, rather than just whatever feels easiest`,`Prioritization has no practical benefit`,`All tasks should always be treated as equally urgent`,`Only urgency matters; importance is irrelevant`], ans:0, exp:`Considering both urgency (how soon something is due) and importance (how much it matters to your goals) helps you focus your limited time on what actually matters most, rather than just what feels most pressing in the moment.` },
      { q:`What is "time blocking"?`, ch:[`Refusing to schedule any specific times for tasks`,`Assigning specific blocks of time in a schedule to specific tasks or activities`,`A term unrelated to scheduling`,`Doing every task at the exact same time`], ans:1, exp:`Time blocking involves dividing your day into dedicated segments for specific tasks (like "7-8pm: Chemistry homework"), which can reduce procrastination and improve focus compared to a vague to-do list.` },
      { q:`Why is it useful to build in buffer time between scheduled tasks or commitments?`, ch:[`Buffer time has no practical use`,`It accounts for tasks running longer than expected and reduces the stress of a tightly packed schedule`,`It guarantees tasks will always finish early`,`Buffer time should only be used for entertainment, never for schoolwork`], ans:1, exp:`Tasks often take longer than planned — building in buffer time between commitments helps absorb those overruns without cascading delays and stress throughout the rest of the day.` },
      { q:`What is procrastination?`, ch:[`Efficiently completing tasks ahead of schedule`,`The tendency to delay starting or completing a task, often despite knowing it may cause problems later`,`A term unrelated to time management`,`A permanent, unchangeable personality trait`], ans:1, exp:`Procrastination is the tendency to put off tasks, often in favor of more immediately pleasant activities, even when a person recognizes the delay could cause stress or problems down the line — and specific strategies (like breaking tasks down or removing distractions) can help manage it.` },
    ],
  },
  {
    id:`fb16`, cat:`Behavioral & Social Sciences`, title:`Study Skills & Test-Taking Strategies`, diff:`Easy`,
    qs:[
      { q:`What is "active recall," as a study technique?`, ch:[`Passively rereading notes repeatedly`,`Actively testing yourself on material (like with flashcards or practice questions) rather than just rereading it`,`A technique unrelated to studying`,`Highlighting text without further review`], ans:1, exp:`Active recall involves actively retrieving information from memory (through self-testing, flashcards, or practice problems), which research consistently shows is far more effective for retention than passively rereading notes.` },
      { q:`Why is passively rereading a textbook generally considered a less effective study strategy than active recall?`, ch:[`Rereading feels easy and creates a false sense of familiarity, without requiring the effortful retrieval that strengthens memory`,`Rereading is scientifically proven to be the most effective study method`,`There is no difference in effectiveness between the two methods`,`Active recall is only useful for math, not other subjects`], ans:0, exp:`Rereading can create an illusion of mastery — the material feels familiar because you just saw it — without requiring the effortful retrieval practice that actually strengthens long-term memory.` },
      { q:`On a multiple-choice test, what is generally a smart first strategy when you're unsure of an answer?`, ch:[`Immediately picking the first option without reading the rest`,`Eliminating answer choices you know are incorrect, then choosing the best remaining option`,`Always leaving the question blank`,`Choosing the longest answer choice automatically`], ans:1, exp:`Eliminating clearly incorrect answer choices first improves your odds even if you're not fully certain of the correct answer, and often helps you spot the right one by process of elimination.` },
      { q:`What is a benefit of taking practice tests under timed, realistic conditions before an actual exam?`, ch:[`It has no benefit compared to just reviewing notes`,`It builds familiarity with the test format and pacing, and helps identify which areas still need more review`,`Practice tests should always be taken with no time limit`,`Practice tests are only useful for the SAT/ACT, not classroom exams`], ans:1, exp:`Timed practice tests build comfort with pacing and format, reduce test-day anxiety through familiarity, and highlight specific content areas that still need more review before the real exam.` },
      { q:`Why might studying in short, focused sessions with brief breaks (like the Pomodoro technique) work better for many students than one long, unbroken study session?`, ch:[`Focus and attention tend to decline over long, unbroken stretches, and short breaks can help sustain concentration`,`Long, unbroken study sessions are always more effective for every student`,`Breaks always reduce total learning with no benefit`,`This technique only works for group study, not individual study`], ans:0, exp:`Sustained focus is hard to maintain for hours at a time — breaking study into shorter, focused intervals with brief breaks can help many students maintain higher-quality concentration throughout a study session.` },
    ],
  },
  {
    id:`fb17`, cat:`Behavioral & Social Sciences`, title:`Note-Taking Methods 101`, diff:`Easy`,
    qs:[
      { q:`What is the Cornell note-taking method?`, ch:[`A method with no organized structure at all`,`A structured method that divides a page into a note-taking area, a cue/question column, and a summary section`,`A method that only allows notes to be typed, never handwritten`,`A method used exclusively for math classes`], ans:1, exp:`The Cornell method divides a page into a main note-taking section, a narrower column for key cues or questions, and a summary section at the bottom, encouraging both organized notes and later self-testing.` },
      { q:`What is an "outline" style of note-taking generally best suited for?`, ch:[`Content that has a clear hierarchical structure, with main topics and supporting subpoints`,`Content with no discernible structure or organization`,`Only for taking notes during lab experiments`,`Content that should never be reviewed again`], ans:0, exp:`Outline notes work well for content with a clear hierarchy — main ideas, supporting details, and sub-details — using indentation to visually represent that structure.` },
      { q:`What is a mind map, as a note-taking technique?`, ch:[`A linear, top-to-bottom list of facts`,`A visual diagram that branches out from a central topic to related subtopics and details`,`A technique that only works for auditory learners`,`A method that discourages making connections between ideas`], ans:1, exp:`A mind map starts with a central concept and branches outward to related ideas and details, visually representing how concepts connect to each other — often helpful for brainstorming or seeing the "big picture."` },
      { q:`Why is it generally more effective to take notes in your own words rather than copying text verbatim?`, ch:[`Copying text verbatim is always the superior method`,`Rephrasing information in your own words requires deeper processing, which improves understanding and retention`,`Note-taking style has no effect on learning`,`Verbatim copying is required for all academic notes`], ans:1, exp:`Putting information into your own words forces you to actually process and understand it, rather than just transcribing — this deeper processing tends to improve both comprehension and later recall.` },
      { q:`What is a practical reason to review and reorganize your notes shortly after a class, rather than waiting until right before a test?`, ch:[`Reviewing notes soon after class has no real benefit`,`Reviewing soon after class, while the material is still fresh, helps identify gaps or confusion early and reinforces the information`,`Notes should never be reviewed more than once`,`Waiting until right before a test is always the more effective strategy`], ans:1, exp:`Reviewing notes soon after class — while the material and context are still fresh — helps catch gaps or points of confusion early, and reinforces the information through that additional exposure.` },
    ],
  },
  {
    id:`fb18`, cat:`Behavioral & Social Sciences`, title:`Building a Strong Study Schedule`, diff:`Easy`,
    qs:[
      { q:`Why is it generally better to plan a weekly study schedule in advance, rather than deciding what to study each day as it comes?`, ch:[`Advance planning has no real advantage`,`Planning ahead helps balance time across subjects, avoid last-minute cramming, and account for upcoming deadlines`,`Daily improvised planning is always more effective`,`Weekly schedules should never include any flexibility`], ans:1, exp:`A weekly plan lets you see upcoming deadlines and balance study time across subjects in advance, reducing the odds of realizing too late that a big test or project has been neglected.` },
      { q:`What is a reasonable strategy for scheduling review of material you've already learned, not just new material?`, ch:[`Never revisiting material once it's initially learned`,`Building in regular, spaced review sessions of earlier material alongside new learning`,`Only reviewing material the night before a final exam`,`Review sessions have no measurable benefit`], ans:1, exp:`Regularly revisiting previously learned material (rather than only moving forward to new content) uses the well-supported "spacing effect" to strengthen long-term retention, rather than relying on a single cram session before a final.` },
      { q:`Why should a realistic study schedule account for non-academic commitments, like sports, work, or family responsibilities?`, ch:[`Non-academic commitments should always be ignored when planning`,`A schedule that ignores real time constraints is unlikely to be followed consistently`,`Only academic time should ever be scheduled`,`This consideration has no effect on whether a schedule is realistic`], ans:1, exp:`A study schedule that doesn't account for real commitments and available time is unlikely to be sustainable — realistic planning around your actual life makes a schedule far more likely to actually be followed.` },
      { q:`What's a potential downside of scheduling every single minute of the day with no flexibility at all?`, ch:[`There is no downside; maximal rigidity is always ideal`,`An overly rigid schedule can become stressful and hard to maintain if anything unexpected comes up`,`Flexibility always makes a schedule less effective`,`Rigid schedules guarantee better academic performance`], ans:1, exp:`Life rarely goes exactly as planned — a schedule with zero flexibility can quickly feel derailed (and stressful) when something unexpected happens, so building in some buffer or flexible time tends to work better long-term.` },
      { q:`Why might reviewing your study schedule at the end of each week be a useful habit?`, ch:[`It has no practical benefit`,`It lets you assess what worked, what didn't, and adjust the following week's plan accordingly`,`Schedules should never be adjusted once created`,`Weekly review is only relevant for very long-term projects`], ans:1, exp:`A brief weekly check-in lets you notice which parts of your schedule worked well and which didn't (like consistently running out of time for one subject), so you can make realistic adjustments going forward.` },
    ],
  },
  {
    id:`fb19`, cat:`Behavioral & Social Sciences`, title:`Growth Mindset 101`, diff:`Easy`,
    qs:[
      { q:`What is a "growth mindset," a concept developed by psychologist Carol Dweck?`, ch:[`The belief that abilities and intelligence are fixed traits that can never improve`,`The belief that abilities and intelligence can be developed over time through effort, strategy, and learning`,`A term unrelated to learning or motivation`,`The belief that talent alone determines success, regardless of effort`], ans:1, exp:`A growth mindset is the belief that intelligence and abilities can be developed through dedication, effective strategies, and learning from mistakes — as opposed to a "fixed mindset," which views ability as a static trait.` },
      { q:`How does someone with a fixed mindset typically respond to failure or a difficult challenge?`, ch:[`They tend to see the challenge as an opportunity to grow`,`They may avoid the challenge or give up more easily, viewing failure as proof of a lack of inherent ability`,`They respond in an identical way to someone with a growth mindset`,`Mindset has no bearing on how someone responds to failure`], ans:1, exp:`A fixed mindset often leads someone to interpret failure as evidence they simply "aren't good" at something, which can lead to avoiding challenges rather than persisting through them.` },
      { q:`How might a growth-mindset student typically respond to a low grade on a test?`, ch:[`Concluding they are simply not capable in that subject and giving up`,`Viewing it as useful feedback and identifying specific strategies to improve for next time`,`Ignoring the grade completely with no reflection`,`Assuming the grade reflects an unchangeable trait`], ans:1, exp:`A growth-mindset response treats a low grade as informative feedback — a signal to identify what went wrong and adjust study strategies — rather than as proof of a fixed, unchangeable limitation.` },
      { q:`What is the role of "effective effort" (not just effort alone) in a growth mindset?`, ch:[`Simply working harder, regardless of strategy, always guarantees success`,`Growth mindset emphasizes using good strategies and learning from feedback, not just working longer or harder without adjusting approach`,`Effort has no role in a growth mindset at all`,`Strategy is irrelevant as long as effort is high`], ans:1, exp:`A common misunderstanding of growth mindset is that "just try harder" is enough — in reality, it emphasizes using effective strategies, seeking feedback, and adjusting your approach, not simply grinding away at an ineffective method.` },
      { q:`Why might praising a student's specific strategies and effort ("You worked through that really methodically") be more helpful for building a growth mindset than praising innate ability ("You're so smart")?`, ch:[`Effort-based praise has no different effect than ability-based praise`,`Praising process and strategy reinforces that improvement comes from effort and approach, while praising fixed ability can discourage risk-taking for fear of "losing" that label`,`Ability-based praise is always more motivating`,`Neither type of praise has any measurable effect on motivation`], ans:1, exp:`Research on praise (notably by Carol Dweck) suggests that praising effort and strategy encourages a growth mindset and resilience, while praising fixed ability can make students more risk-averse, since failure might threaten their "smart" label.` },
    ],
  },
  {
    id:`fb20`, cat:`Behavioral & Social Sciences`, title:`Managing Test Anxiety`, diff:`Medium`,
    qs:[
      { q:`What is test anxiety?`, ch:[`A permanent learning disability`,`A form of performance anxiety involving excessive worry, physical tension, and distraction specifically related to test-taking situations`,`A term unrelated to testing`,`A condition that only affects students with low academic ability`], ans:1, exp:`Test anxiety is a specific type of performance anxiety marked by excessive worry, physical symptoms (like a racing heart), and difficulty concentrating, specifically triggered by testing situations — and it can affect students of any ability level.` },
      { q:`How can thorough preparation help reduce test anxiety?`, ch:[`Preparation has no effect on anxiety levels`,`Feeling genuinely prepared can increase confidence and reduce the uncertainty that often fuels anxiety`,`Preparation always makes test anxiety worse`,`Only guessing at test content reduces anxiety`], ans:1, exp:`Much test anxiety stems from uncertainty about whether you know the material — thorough, spaced-out preparation (rather than last-minute cramming) tends to build genuine confidence that can ease that anxiety.` },
      { q:`What is a simple, evidence-based technique that can help calm physical symptoms of anxiety right before or during a test?`, ch:[`Holding your breath for as long as possible`,`Slow, deep breathing to help calm the body's physiological stress response`,`Avoiding any breathing regulation entirely`,`Rapid, shallow breathing to increase alertness`], ans:1, exp:`Slow, controlled breathing helps activate the body's relaxation response, countering the rapid heart rate and shallow breathing associated with the stress response, which can help calm test-related anxiety in the moment.` },
      { q:`Why might reframing negative thoughts ("I'm going to fail") into more balanced ones ("I've prepared, and I'll do my best") help with test anxiety?`, ch:[`Reframing thoughts has no effect on anxiety or performance`,`Catastrophic thinking tends to increase anxiety, while more balanced, realistic thoughts can reduce anxious arousal and support better focus`,`Negative self-talk always improves test performance`,`Thought patterns are unrelated to anxiety symptoms`], ans:1, exp:`Catastrophic thinking patterns tend to amplify anxiety, while consciously reframing thoughts in a more balanced, realistic way is a well-supported cognitive strategy for reducing anxiety and supporting better focus during a test.` },
      { q:`Why might arriving early and being familiar with the testing format/logistics help reduce anxiety on test day?`, ch:[`It has no effect on anxiety levels`,`Reducing unfamiliar or unexpected elements (like rushing, or not knowing the format) removes extra sources of stress, letting a student focus on the actual content`,`Arriving early always increases stress`,`Familiarity with logistics has no bearing on anxiety`], ans:1, exp:`Extra, avoidable stressors — like rushing to arrive or being unsure what to expect — can compound test anxiety. Removing those variables in advance frees up mental energy to focus on the actual test content.` },
    ],
  },
  {
    id:`fb21`, cat:`Behavioral & Social Sciences`, title:`SAT/ACT Prep Basics: Reading Strategies`, diff:`Medium`,
    qs:[
      { q:`Why is it often helpful to read the questions (or at least skim them) before diving deeply into a long reading passage on the SAT/ACT?`, ch:[`Questions have no connection to what to look for in the passage`,`It gives you a sense of what to look for, helping you focus your reading and manage time more efficiently`,`Reading questions first is always against the rules`,`It has no effect on speed or comprehension`], ans:1, exp:`Previewing questions (even briefly) can help direct your attention to the most relevant parts of a passage, which can save time and improve focus compared to reading with no sense of what you're looking for.` },
      { q:`When answering an evidence-based reading question that asks for the best textual support for a previous answer, what's the most reliable strategy?`, ch:[`Picking whichever answer choice sounds most impressive`,`Going back to the passage and finding the specific line(s) that directly support the previous answer, then matching that to the choices`,`Guessing without rechecking the passage at all`,`Ignoring the passage and relying purely on memory`], ans:1, exp:`Evidence-based questions require directly verifying your answer against specific lines in the passage — going back to check rather than relying on memory or gut feeling improves accuracy significantly.` },
      { q:`What is a common trap in multiple-choice reading questions, where an answer choice seems appealing but is actually incorrect?`, ch:[`An answer that is a broader, well-supported summary of the passage`,`An answer that uses similar words from the passage but distorts or misrepresents its actual meaning`,`An answer that directly restates the correct part of the passage accurately`,`There are no common traps in reading questions`], ans:1, exp:`Test writers often include "trap" answers that echo specific words or phrases from the passage but subtly twist or misrepresent the actual meaning — careful, close reading helps avoid falling for these.` },
      { q:`Why is time management especially important on standardized reading sections?`, ch:[`Time management has no bearing on reading section performance`,`Spending too long on one passage or question can leave insufficient time for others, reducing your overall score`,`Reading sections have no time limit`,`Rushing through every passage always improves accuracy`], ans:1, exp:`Reading sections are timed, and passages/questions vary in difficulty — pacing yourself and being willing to move on from a particularly difficult question helps ensure you have time to attempt every passage.` },
      { q:`What is generally the best approach if you're unsure between two remaining answer choices after eliminating the obviously wrong ones?`, ch:[`Pick whichever one is most directly supported by specific evidence in the passage`,`Always pick the longer of the two answer choices`,`Flip a coin without reconsidering the passage`,`Choose the answer that uses the most sophisticated vocabulary`], ans:0, exp:`When narrowing down to two choices, go back to the specific evidence in the passage — the correct answer should be directly and specifically supported by the text, not just generally plausible.` },
    ],
  },
  {
    id:`fb22`, cat:`Behavioral & Social Sciences`, title:`SAT/ACT Prep Basics: Math Strategies`, diff:`Medium`,
    qs:[
      { q:`Why can "plugging in" answer choices sometimes be a faster strategy than solving an algebra problem directly?`, ch:[`Plugging in answer choices is never a valid strategy`,`For some multiple-choice problems, testing the given numerical answer choices in the original equation can be quicker than solving algebraically from scratch`,`Plugging in only works for geometry problems`,`This strategy always produces the wrong answer`], ans:1, exp:`On multiple-choice math questions, especially with numerical answer choices, testing each option directly in the original problem can sometimes be faster and less error-prone than working through the full algebra.` },
      { q:`Why is it valuable to skip a difficult math question temporarily and come back to it later, rather than getting stuck?`, ch:[`Skipping questions always results in a lower score`,`It ensures you have time to answer every question you're confident about, without losing time on one difficult problem`,`Standardized tests don't allow skipping questions`,`There's no benefit to managing time this way`], ans:1, exp:`Since every correctly answered question generally counts equally toward your score, getting stuck on one hard question can cost you points elsewhere by eating into time needed for questions you could easily answer.` },
      { q:`Why is it useful to double-check that your final answer actually addresses what the question is asking?`, ch:[`It's an unnecessary step that wastes time`,`Some problems ask for a specific value (like x+1) rather than the variable itself (x), and it's easy to answer the wrong part if you're not careful`,`Questions are never worded to test this kind of care`,`Double-checking always changes a correct answer to an incorrect one`], ans:1, exp:`A common source of avoidable errors is solving correctly but answering the wrong thing — like finding x when the question actually asked for 2x, or y - 3 — so reviewing exactly what's being asked is an important final check.` },
      { q:`Why might drawing a diagram or sketch help with a geometry word problem, even if one isn't provided?`, ch:[`Diagrams have no value if the problem is described in words`,`Visualizing the problem can reveal relationships between shapes, angles, or values that are harder to track mentally`,`Drawing a diagram is against the rules on standardized tests`,`Diagrams only help with algebra, never geometry`], ans:1, exp:`Sketching a quick diagram for a geometry problem, even a rough one, often makes spatial relationships (like which angles or sides correspond) far easier to track than trying to hold everything in your head.` },
      { q:`Why is it worth memorizing a handful of common formulas (like area, the Pythagorean theorem, or slope) ahead of time, even if some are provided on the test?`, ch:[`Memorizing formulas provides no time-saving benefit`,`Quick, automatic recall of common formulas saves time you'd otherwise spend looking them up or rederiving them mid-test`,`Formulas are never useful on standardized math sections`,`It's always faster to derive every formula from scratch during the test`], ans:1, exp:`Even when some formulas are provided on a reference sheet, quickly and automatically recalling common ones (rather than searching for or rederiving them) saves valuable time during a timed test.` },
    ],
  },
  {
    id:`fb23`, cat:`Behavioral & Social Sciences`, title:`College Essay Writing 101`, diff:`Medium`,
    qs:[
      { q:`What is generally the main purpose of a college application essay?`, ch:[`To restate your resume or list of activities in paragraph form`,`To give admissions readers insight into your personality, values, and voice beyond what grades and test scores show`,`To demonstrate advanced vocabulary with no other goal`,`To describe your school's history and reputation`], ans:1, exp:`A college essay's main purpose is to reveal something genuine and specific about who you are — your perspective, values, or growth — that a transcript and activities list alone can't capture.` },
      { q:`Why do admissions readers often prefer a specific, personal story over a broad, general statement in an essay?`, ch:[`Specific stories are actually discouraged by admissions readers`,`Specific, concrete details make an essay feel authentic and memorable, while broad generalizations can feel generic and forgettable`,`General statements are always more persuasive`,`Specificity has no impact on how an essay is received`], ans:1, exp:`A vivid, specific story or detail (a real moment, a real conversation) tends to stick with a reader and feels authentic, whereas broad, generic statements ("I've always loved helping people") could describe almost anyone.` },
      { q:`Why is it usually a mistake to try to cover too many different topics or experiences in a single short college essay?`, ch:[`Covering many topics always strengthens an essay`,`Trying to cover too much often means no single idea gets developed with enough depth or reflection`,`Essays are strongest when they read like a list of accomplishments`,`There's no downside to covering many topics briefly`], ans:1, exp:`Given a tight word limit, spreading attention across too many topics usually means none of them get the depth, reflection, or specific detail that makes an essay compelling — a narrower, well-developed focus is usually stronger.` },
      { q:`What does it typically mean for an essay to show genuine "reflection," rather than just recounting events?`, ch:[`Simply describing what happened, in chronological order, with no further analysis`,`Explaining what an experience meant to the writer, what they learned, or how it changed their thinking`,`Reflection is not something admissions readers value`,`Only listing accomplishments, without any personal insight`], ans:1, exp:`Strong essays go beyond just narrating what happened — they explore what the experience meant, what the writer learned or how they grew, giving the reader insight into the writer's actual thinking.` },
      { q:`Why is it valuable to have someone else (a teacher, counselor, or family member) review a draft of your essay before submitting it?`, ch:[`Outside feedback has no real value for essay writing`,`A fresh set of eyes can catch unclear passages, typos, or places where your intended meaning isn't coming across`,`Essays should never be shown to anyone before submission`,`Reviewers will always rewrite the essay in a way that erases your voice`], ans:1, exp:`A trusted reader can catch confusing passages, typos, or gaps between what you meant and what actually came across on the page — while good feedback should sharpen your essay, not replace your own voice.` },
    ],
  },
  {
    id:`fb24`, cat:`Behavioral & Social Sciences`, title:`Extracurriculars That Matter`, diff:`Easy`,
    qs:[
      { q:`Why do college and program admissions committees often value depth in a few activities over surface-level involvement in many?`, ch:[`Depth has no advantage over breadth`,`Sustained, meaningful involvement in a few activities usually demonstrates more commitment, growth, and impact than briefly joining many clubs`,`Admissions committees only care about the total number of activities listed`,`Breadth is always preferred over depth in every case`], ans:1, exp:`Colleges generally look for evidence of sustained commitment and real impact — a student deeply involved in two or three activities over years often stands out more than one who joined a dozen clubs briefly with minimal real involvement.` },
      { q:`What is one sign that an extracurricular activity had genuine impact, beyond just attendance?`, ch:[`Simply being listed as a member with no further involvement`,`Taking on a leadership role, initiating a project, or measurably improving something within the activity`,`Attending the minimum number of meetings required`,`Impact cannot be demonstrated through extracurriculars at all`], ans:1, exp:`Concrete evidence of impact — starting a new initiative, taking on real responsibility, leading a team, or solving a specific problem — shows more than simply being a passive member of a club.` },
      { q:`Why might an unusual or personally meaningful activity (not a typical "pre-med checklist" item) sometimes be more compelling on an application than a generic one?`, ch:[`Unusual activities are always penalized by admissions readers`,`Genuine, personally meaningful involvement often comes through as more authentic and memorable than an activity chosen purely because it "looks good"`,`Only medically related activities are ever considered valuable`,`Personal interest has no bearing on how an activity reads on an application`], ans:1, exp:`Admissions readers can often tell the difference between an activity pursued out of genuine interest and one chosen only because it seems expected — authentic engagement tends to produce a more compelling, specific story.` },
      { q:`Why is consistency over multiple years generally viewed more favorably than an activity picked up only in senior year?`, ch:[`Consistency has no bearing on how an activity is perceived`,`Sustained, multi-year involvement suggests real, lasting interest and commitment rather than something done just to build a resume late in high school`,`Activities started senior year are always viewed more favorably`,`Only activities from freshman year count toward an application`], ans:1, exp:`An activity sustained over multiple years signals genuine interest and follow-through, whereas an activity that appears suddenly only in senior year can sometimes read as a late addition aimed mainly at the application itself.` },
      { q:`Why might quality of reflection about an extracurricular (in an essay or interview) matter as much as the activity itself?`, ch:[`Reflection has no bearing on how an activity is perceived`,`Being able to articulate what you learned or how you grew from an experience demonstrates self-awareness and genuine engagement`,`Only the raw hours logged for an activity matter, with no need for reflection`,`Admissions readers never ask about extracurricular activities`], ans:1, exp:`Two students with identical activities can present very differently depending on whether they can articulate what the experience taught them — thoughtful reflection often matters as much as the activity itself.` },
    ],
  },
  {
    id:`fb25`, cat:`Behavioral & Social Sciences`, title:`Financial Aid & FAFSA Basics`, diff:`Medium`,
    qs:[
      { q:`What does FAFSA stand for?`, ch:[`Federal Application for Student Financial Aid`,`Free Application for Federal Student Aid`,`Financial Assistance for Federal Student Applicants`,`Federal Aid For Students Attending`], ans:1, exp:`FAFSA stands for the Free Application for Federal Student Aid — the standard application most US students use to apply for federal (and often state and school-based) financial aid.` },
      { q:`What is the general purpose of completing the FAFSA?`, ch:[`It has no real purpose beyond a formality`,`It's used to determine a student's eligibility for federal grants, loans, and work-study, and is often required for state and school aid too`,`It only applies to students planning to attend graduate school`,`It replaces the need to apply to individual colleges`], ans:1, exp:`The FAFSA collects financial information used to calculate a student's eligibility for various forms of financial aid — including federal grants, loans, and work-study — and many states and individual colleges use it too.` },
      { q:`What is the difference between a grant/scholarship and a student loan?`, ch:[`They are functionally identical`,`Grants and scholarships generally do not need to be repaid; loans must be repaid, typically with interest`,`Loans never need to be repaid`,`Grants and scholarships must always be repaid after graduation`], ans:1, exp:`Grants and scholarships are essentially "gift aid" that generally doesn't need to be repaid, while loans provide money upfront that must be paid back over time, usually with interest.` },
      { q:`What is work-study, as a form of financial aid?`, ch:[`A loan that must be repaid with high interest`,`A federally funded program that provides part-time job opportunities, often on campus, to help eligible students earn money for expenses`,`A scholarship awarded purely for academic performance`,`A term unrelated to financial aid`], ans:1, exp:`Federal work-study provides eligible students with part-time job opportunities (often on campus) as a way to earn money toward educational expenses, and it's factored into a student's overall financial aid package.` },
      { q:`Why is it generally recommended to complete the FAFSA as early as possible once it opens each year?`, ch:[`Filing early has no advantage over filing later`,`Some financial aid (including certain grants and scholarships) is awarded on a first-come, first-served basis, so filing early can maximize the aid a student receives`,`The FAFSA is only available for a single day each year`,`Filing later always results in more aid`], ans:1, exp:`Because some aid programs have limited funds and award on a first-come, first-served basis, submitting the FAFSA as soon as it becomes available can meaningfully increase a student's chances of receiving certain aid.` },
    ],
  },
  {
    id:`fb26`, cat:`Behavioral & Social Sciences`, title:`Choosing a College Major`, diff:`Easy`,
    qs:[
      { q:`For a student aiming for medical school, is it required to major in a specific "pre-med" major like biology?`, ch:[`Yes, only a biology major is ever accepted to medical school`,`No — medical schools accept students from virtually any major, as long as required prerequisite coursework is completed`,`Only chemistry majors are accepted to medical school`,`Choosing a major has no relevance to medical school admissions at all`], ans:1, exp:`Medical schools don't require a specific major — they require certain prerequisite courses (like biology, chemistry, physics) to be completed regardless of major, so students can major in something they're genuinely interested in, even outside the sciences.` },
      { q:`Why might it be a mistake to choose a college major purely because it seems "practical," without any genuine interest in it?`, ch:[`Practicality is the only factor that should ever matter`,`Sustained motivation and strong performance are harder to maintain in a field a student has little genuine interest in`,`Interest has no bearing on academic performance`,`Choosing based on interest always leads to worse outcomes`], ans:1, exp:`Genuine interest tends to fuel motivation, engagement, and stronger academic performance — a major chosen purely for perceived practicality, with no real interest, can be harder to sustain through several demanding years of coursework.` },
      { q:`What is a reasonable way for an undecided high schooler to start narrowing down potential college majors?`, ch:[`Picking a major at random with no further research`,`Reflecting on classes and activities they've genuinely enjoyed, and researching what careers and coursework different majors actually involve`,`Choosing whatever major their friends are choosing`,`Avoiding any research and deciding only after starting college`], ans:1, exp:`Reflecting on which classes, projects, or activities have genuinely engaged you, combined with researching what different majors actually involve day-to-day, is a practical way to start narrowing down options.` },
      { q:`Is it generally possible to change majors after starting college?`, ch:[`No, majors are permanently fixed once chosen`,`Yes — many students change majors at least once, though switching can sometimes affect time-to-graduation depending on the specific majors involved`,`Only students in certain majors are ever allowed to switch`,`Changing majors is not allowed at any US college`], ans:1, exp:`Changing majors is common and generally allowed at most colleges, though switching between very different fields partway through can sometimes require additional coursework or affect graduation timelines.` },
      { q:`Why might exploring a range of introductory courses in the first year or two of college be helpful for students who are unsure of a major?`, ch:[`Exploring introductory courses has no practical benefit`,`It provides direct, low-stakes exposure to different fields, helping a student make a more informed decision based on actual coursework rather than assumptions`,`Students should commit to a major before ever taking a related course`,`Only one introductory course should ever be taken throughout college`], ans:1, exp:`Taking a variety of introductory courses lets students experience what a field is actually like firsthand, which often leads to a more informed and confident major decision than guessing based on assumptions alone.` },
    ],
  },
  {
    id:`fb27`, cat:`Behavioral & Social Sciences`, title:`Campus Visits & Finding the Right College Fit`, diff:`Easy`,
    qs:[
      { q:`What does "college fit" generally refer to?`, ch:[`Only a school's ranking or prestige`,`How well a particular college's environment, size, culture, and offerings align with a student's needs, goals, and preferences`,`A term unrelated to choosing a college`,`Only whether a school has a specific major listed`], ans:1, exp:`College fit describes the overall match between a student's academic, social, and personal needs and preferences, and what a particular school actually offers — beyond just its name or ranking.` },
      { q:`Why might visiting a college campus in person (when possible) provide insight that a website or brochure can't?`, ch:[`Campus visits provide no additional insight beyond a website`,`Being physically present lets a student experience the actual atmosphere, talk to current students, and sit in on a class, which is hard to fully capture online`,`Only virtual tours provide useful information`,`Visits should be avoided since they add no value`], ans:1, exp:`Walking around campus, talking informally with current students, and sitting in on an actual class can reveal a school's day-to-day feel and culture in ways that a polished website or brochure often can't fully convey.` },
      { q:`Why might a student's preference for a large city environment versus a small, rural campus matter when evaluating fit?`, ch:[`Location and setting have no bearing on a student's overall college experience`,`A student's daily happiness and engagement can be affected by whether the setting matches their personal preferences and comfort level`,`Every student thrives equally well in every type of setting`,`This factor is irrelevant to college selection`], ans:1, exp:`A student's day-to-day well-being and engagement can genuinely be affected by whether a school's setting (urban, suburban, rural; large or small) matches what they find comfortable and energizing.` },
      { q:`Why shouldn't a college's overall ranking be the only factor a student considers when evaluating fit?`, ch:[`Rankings should be the sole deciding factor for every student`,`A school's ranking doesn't necessarily reflect how well it matches a specific student's needs, learning style, or goals`,`Rankings are entirely meaningless with zero informational value`,`Fit and ranking are always perfectly correlated`], ans:1, exp:`A highly ranked school might still be a poor fit for a specific student's needs (learning style, desired class sizes, campus culture, or specific program strengths) — rankings are one data point, not a complete picture of fit.` },
      { q:`What is one practical way a student can learn about a college's academic support resources (like tutoring or advising) before applying or enrolling?`, ch:[`Assuming every school offers identical support with no need to check`,`Researching the school's website, asking current students, or contacting the admissions office directly with specific questions`,`These resources cannot be researched before enrolling`,`Only relying on a school's overall reputation, with no direct research`], ans:1, exp:`Directly researching a school's specific academic support resources — through its website, current students, or the admissions office — gives a much clearer picture than relying on general reputation alone.` },
    ],
  },
  {
    id:`fb28`, cat:`Behavioral & Social Sciences`, title:`Interview Skills 101`, diff:`Medium`,
    qs:[
      { q:`Why is preparing specific, concrete examples from your own experience valuable before an interview?`, ch:[`Specific examples have no advantage over vague, general answers`,`Concrete examples make your answers more memorable, credible, and demonstrate real experience rather than generic claims`,`Interviewers prefer answers with no supporting detail`,`Preparation before an interview is generally discouraged`], ans:1, exp:`A specific story ("Here's a time I handled a difficult situation...") is far more memorable and convincing to an interviewer than a vague, general claim ("I'm good at handling difficult situations").` },
      { q:`Why is it important to research an organization or program before an interview with them?`, ch:[`Research has no bearing on interview performance`,`It shows genuine interest and allows you to ask more informed, specific questions and tailor your answers appropriately`,`Interviewers never expect candidates to know anything about the organization`,`Only the interviewer should know about the organization, not the candidate`], ans:1, exp:`Understanding an organization's mission, values, or specific program details lets you tailor your answers and ask thoughtful questions, signaling genuine interest and preparation.` },
      { q:`What does maintaining good eye contact and open body language during an interview generally communicate?`, ch:[`Nothing meaningful; body language is irrelevant in interviews`,`Confidence, engagement, and attentiveness`,`Only nervousness and discomfort`,`Body language only matters in video interviews, never in person`], ans:1, exp:`Nonverbal cues like appropriate eye contact and open, attentive body language generally signal confidence and genuine engagement with the conversation, complementing your verbal answers.` },
      { q:`Why is it useful to prepare a few thoughtful questions to ask the interviewer at the end of the conversation?`, ch:[`Asking questions is generally discouraged in interviews`,`It demonstrates genuine curiosity and engagement, and helps you evaluate whether the opportunity is a good fit for you too`,`Questions should only ever be about salary or logistics`,`Interviewers never expect or want candidates to ask questions`], ans:1, exp:`Thoughtful questions show genuine engagement and curiosity about the role or program, and also give you useful information to evaluate whether the opportunity is actually a good fit for your own goals.` },
      { q:`If you're asked a challenging or unexpected question you didn't prepare for, what's generally a better approach than freezing up?`, ch:[`Refusing to answer at all`,`Taking a brief moment to think, then giving an honest, thoughtful answer, even if it's not perfectly polished`,`Making up a completely fabricated answer`,`Ending the interview immediately`], ans:1, exp:`It's normal not to have a perfectly polished answer to every question — pausing briefly to gather your thoughts and giving an honest, considered response is generally received far better than freezing up or fabricating an answer.` },
    ],
  },
  {
    id:`fb29`, cat:`Behavioral & Social Sciences`, title:`Group Project & Teamwork Skills`, diff:`Easy`,
    qs:[
      { q:`Why is establishing clear roles and responsibilities early in a group project generally helpful?`, ch:[`Clear roles have no effect on how smoothly a project runs`,`It reduces confusion about who is doing what, and helps ensure all necessary tasks actually get covered`,`Assigning roles always slows down a group's progress`,`Every group member should always do the exact same tasks`], ans:1, exp:`Defining who is responsible for which parts of a project early on reduces duplicated effort, uncovered gaps, and confusion, making the overall process smoother and more efficient.` },
      { q:`What is a constructive way to handle a group member who consistently isn't contributing their fair share?`, ch:[`Silently doing all their work for them with no conversation`,`Having a direct, respectful conversation about expectations, and involving a teacher/supervisor if the issue continues`,`Publicly criticizing them in front of others with no private conversation first`,`Ignoring the issue completely and hoping it resolves itself`], ans:1, exp:`A calm, direct conversation about specific expectations is usually the most constructive first step; if the issue persists, involving a teacher or supervisor appropriately can help resolve it fairly.` },
      { q:`Why is it valuable for a group to agree on a shared timeline with specific milestones, rather than one final deadline?`, ch:[`A single final deadline is always more effective`,`Milestones help track progress along the way and catch problems early, rather than discovering issues only right before the final deadline`,`Milestones have no practical benefit for group work`,`Timelines should never include any intermediate checkpoints`], ans:1, exp:`Breaking a project into milestones with intermediate check-ins helps a group notice if something is falling behind schedule early enough to address it, rather than only discovering a problem right before the final deadline.` },
      { q:`What is "social loafing," a phenomenon sometimes observed in group work?`, ch:[`Everyone in a group always contributing equally`,`The tendency for individuals to exert less effort on a task when working in a group than when working alone`,`A term unrelated to group dynamics`,`A phenomenon that only affects very small groups`], ans:1, exp:`Social loafing describes the tendency for people to put in less individual effort in a group setting than they would if working alone — often because individual contributions feel less visible or less directly accountable.` },
      { q:`Why can giving and receiving constructive feedback be an important skill within group work?`, ch:[`Feedback should always be avoided to prevent conflict`,`Constructive feedback, given respectfully, helps improve the quality of the final product and strengthens how the group works together`,`Feedback has no effect on the outcome of a group project`,`Only the group leader should ever offer feedback`], ans:1, exp:`Respectful, specific feedback (both giving and receiving it) helps catch issues early and improve the final product, and it's a skill valuable well beyond a single group project.` },
    ],
  },
  {
    id:`fb30`, cat:`Behavioral & Social Sciences`, title:`Public Speaking Basics`, diff:`Easy`,
    qs:[
      { q:`Why does thoroughly practicing a speech or presentation out loud, in advance, generally improve performance?`, ch:[`Practicing has no measurable effect on speaking performance`,`Speaking practice builds familiarity with the material and pacing, and helps identify awkward phrasing before the actual presentation`,`Only reading the material silently is an effective way to prepare`,`Practicing out loud always makes a speaker more nervous`], ans:1, exp:`Practicing out loud (not just reading silently) helps build comfort with pacing, timing, and phrasing, and often reveals awkward transitions or unclear wording that aren't obvious when just reading text on a page.` },
      { q:`Why is making eye contact with an audience generally recommended during a presentation?`, ch:[`Eye contact has no effect on audience engagement`,`It helps build connection with the audience and can make a speaker appear more confident and engaged`,`Speakers should always look only at their notes`,`Eye contact only matters in written communication`], ans:1, exp:`Making eye contact with different parts of an audience helps build a sense of connection and generally makes a speaker appear more confident, credible, and engaged with the audience.` },
      { q:`What is a common recommendation for managing nervousness right before public speaking?`, ch:[`Avoiding any preparation to reduce pressure`,`Practicing beforehand, using slow breathing techniques, and reframing nervous energy as excitement`,`Ignoring all nervousness with no strategy at all`,`Speaking as quickly as possible to get it over with`], ans:1, exp:`Thorough practice, slow breathing to calm physiological arousal, and consciously reframing nervous energy as excitement (rather than fear) are all commonly recommended, evidence-supported strategies for managing public speaking anxiety.` },
      { q:`Why is varying your vocal tone and pace during a speech generally more engaging than speaking in a flat monotone?`, ch:[`Vocal variety has no effect on audience engagement`,`Vocal variety helps emphasize key points and keeps an audience's attention, while a monotone can make even interesting content feel dull`,`Monotone delivery is always more professional`,`Audiences prefer speakers to speak as quickly as possible throughout`], ans:1, exp:`Varying your pace, volume, and tone helps emphasize important points and keeps an audience engaged, while a flat, unchanging monotone delivery can make it harder for listeners to stay focused, even on strong content.` },
      { q:`Why might using clear structure (like an introduction, a few main points, and a conclusion) help an audience follow a presentation?`, ch:[`Structure has no effect on how well an audience follows a talk`,`A clear structure helps the audience track where the speaker is in the presentation and how each point connects to the overall message`,`Presentations are always more effective with no clear organization`,`Only written documents benefit from clear structure`], ans:1, exp:`A clear, predictable structure gives an audience a mental map of the presentation, making it much easier to follow the flow of ideas and understand how each part connects to the overall point.` },
    ],
  },
  {
    id:`fb31`, cat:`Behavioral & Social Sciences`, title:`Digital Citizenship & Online Presence`, diff:`Easy`,
    qs:[
      { q:`What is digital citizenship?`, ch:[`A legal status granted only to adults`,`The responsible, ethical, and safe use of technology and online spaces`,`A term unrelated to internet use`,`Only a technical term used by computer engineers`], ans:1, exp:`Digital citizenship refers to using technology and the internet responsibly, safely, and ethically — including how you communicate, share information, and treat others online.` },
      { q:`Why might college admissions officers or future employers sometimes look at a student's public social media presence?`, ch:[`They never consider social media in any evaluation`,`Public online content can offer additional insight into a person's character, judgment, and values, alongside the rest of an application`,`Social media presence is entirely private and cannot be viewed by anyone`,`Social media has no bearing whatsoever on any evaluation process`], ans:1, exp:`While not the primary factor, some admissions offices and employers do review publicly available social media content, which can provide additional (though limited) context about a candidate's judgment and character.` },
      { q:`What is a reasonable general guideline for what to post publicly online?`, ch:[`Assume that anything posted publicly could potentially be seen by someone like a future employer, admissions officer, or family member`,`Assume nothing posted online is ever seen by anyone beyond your close friends`,`Privacy settings make it impossible for any public content to ever be seen by others`,`There's no need to think carefully about what you post publicly`], ans:0, exp:`A reasonable practical guideline is to assume that publicly posted content could be seen by a wider audience than originally intended, including people evaluating you in the future — which encourages more thoughtful posting.` },
      { q:`What is "digital footprint"?`, ch:[`A term unrelated to internet activity`,`The trail of data and content a person leaves behind through their online activity over time`,`A physical device used to measure internet speed`,`A term describing only offline, in-person interactions`], ans:1, exp:`A digital footprint is the accumulated record of a person's online activity — posts, comments, photos, and other data — that can persist and be discovered well after it was originally created.` },
      { q:`Why is it good practice to pause before posting something in the heat of a strong emotional reaction (like anger)?`, ch:[`Pausing has no effect on the quality or impact of a post`,`Content posted impulsively during strong emotion is more likely to be regretted later, since online posts can be difficult to fully take back`,`Immediate posting is always the best strategy for authenticity`,`Emotional posts are never seen by anyone besides close friends`], ans:1, exp:`Once something is posted online, it can be screenshotted, shared, or archived even after deletion — pausing before posting during strong emotion reduces the risk of posting something you'll later regret.` },
    ],
  },
  {
    id:`fb32`, cat:`Behavioral & Social Sciences`, title:`Ethics Basics: Making Good Decisions`, diff:`Medium`,
    qs:[
      { q:`What does "ethics" broadly refer to?`, ch:[`A single, universally agreed-upon set of laws`,`The study of moral principles that guide judgments about right and wrong behavior`,`A term unrelated to decision-making`,`A field that has no connection to real-world choices`], ans:1, exp:`Ethics is the branch of study concerned with what counts as right and wrong behavior, and the reasoning and principles people use to make moral judgments and decisions.` },
      { q:`What is the difference between something being illegal and something being unethical?`, ch:[`They always mean exactly the same thing`,`An action can be legal but still widely considered unethical, or illegal in one place but considered ethical by many, since law and ethics don't always perfectly overlap`,`Illegal actions are always ethical`,`Ethics has no relevance once a law exists on a topic`], ans:1, exp:`Law and ethics often overlap, but not always — some legal actions are widely viewed as unethical (like certain forms of deception that aren't technically illegal), and ethical questions can exist in situations the law doesn't address at all.` },
      { q:`Why might healthcare professions place a strong emphasis on ethical principles like patient confidentiality?`, ch:[`Ethical principles have no real relevance to patient care`,`Protecting sensitive patient information maintains trust, which is foundational to an effective patient-provider relationship`,`Confidentiality is only relevant for legal reasons, with no ethical dimension`,`Ethical principles only apply to research, never direct patient care`], ans:1, exp:`Maintaining patient confidentiality supports trust between patients and healthcare providers — patients need to feel safe sharing sensitive information for effective, honest care, which is why confidentiality is treated as a core ethical (and legal) principle.` },
      { q:`What is an "ethical dilemma"?`, ch:[`A situation with an obvious, universally agreed-upon correct answer`,`A situation where reasonable ethical principles or values seem to conflict, making the "right" choice genuinely difficult to determine`,`A term unrelated to decision-making`,`A dilemma that only exists in hypothetical, fictional scenarios`], ans:1, exp:`An ethical dilemma arises when different ethical principles or values point in different directions, making it genuinely difficult to identify a single clearly "correct" choice — these situations often require careful, thoughtful reasoning rather than a simple rule.` },
      { q:`Why is considering multiple perspectives (not just your own) often recommended when working through an ethical question?`, ch:[`Considering other perspectives has no value in ethical reasoning`,`Different stakeholders may be affected differently, and considering multiple viewpoints leads to more thoughtful, well-rounded decisions`,`Only your own perspective should ever be considered`,`Ethical questions never involve more than one affected party`], ans:1, exp:`Many ethical situations affect multiple people in different ways — deliberately considering how a decision affects various stakeholders tends to produce more thoughtful, well-reasoned conclusions than considering only your own immediate perspective.` },
    ],
  },
  {
    id:`fb33`, cat:`Behavioral & Social Sciences`, title:`Leadership Basics`, diff:`Easy`,
    qs:[
      { q:`Is formal authority (like an official title) required to demonstrate leadership?`, ch:[`Yes, only people with an official title can ever demonstrate leadership`,`No — leadership can be shown through initiative, influence, and action, regardless of formal title or position`,`Leadership is only possible for adults`,`Leadership has no connection to initiative or influence`], ans:1, exp:`Leadership isn't limited to formal titles — a student can demonstrate real leadership by taking initiative, organizing others, or driving a project forward, even without an official leadership position.` },
      { q:`What is servant leadership?`, ch:[`A leadership style focused entirely on the leader's own personal recognition`,`A leadership approach that prioritizes serving and supporting the needs of the team or group first`,`A term unrelated to leadership styles`,`A style where the leader makes all decisions with no input from others`], ans:1, exp:`Servant leadership is an approach where the leader's primary focus is on serving and empowering the people they lead, prioritizing the team's needs and growth over the leader's own status.` },
      { q:`Why is active listening often considered an important leadership skill?`, ch:[`Listening has no relevance to effective leadership`,`Genuinely listening to team members' ideas and concerns builds trust and often leads to better decisions`,`Effective leaders should only speak, never listen`,`Listening skills are only relevant for followers, not leaders`], ans:1, exp:`Leaders who genuinely listen to their team's ideas, concerns, and feedback tend to build stronger trust and often make better-informed decisions than those who don't seek input from others.` },
      { q:`Why might delegating tasks effectively be an important leadership skill, rather than trying to do everything yourself?`, ch:[`Delegation has no impact on a team's overall effectiveness`,`Delegating tasks according to team members' strengths allows a group to accomplish more collectively, and helps develop others' skills`,`Effective leaders should always do every task personally`,`Delegating tasks always results in worse outcomes`], ans:1, exp:`Trying to personally handle every task limits what a group can accomplish and can lead to burnout — delegating appropriately, based on team members' strengths, allows more to get done and helps develop other people's skills too.` },
      { q:`What is one way a student without an official leadership title could still demonstrate leadership within a club or team?`, ch:[`Waiting passively for someone else to take initiative on every task`,`Proactively identifying a problem and organizing a solution, even informally`,`Leadership is impossible without an assigned title`,`Avoiding any responsibility to prevent conflict`], ans:1, exp:`Proactively noticing a gap or problem — and taking initiative to organize people or resources to address it — is a genuine demonstration of leadership, regardless of whether the student holds an official title.` },
    ],
  },
  {
    id:`fb34`, cat:`Behavioral & Social Sciences`, title:`Goal Setting: SMART Goals`, diff:`Easy`,
    qs:[
      { q:`What does the "S" in SMART goals stand for?`, ch:[`Simple`,`Specific`,`Slow`,`Social`], ans:1, exp:`The "S" in SMART goals stands for Specific — a well-defined goal clearly states exactly what you want to accomplish, rather than something vague.` },
      { q:`What does the "M" in SMART goals stand for, and why does it matter?`, ch:[`Measurable — allowing you to track concrete progress and know when the goal has been achieved`,`Mysterious — goals should remain vague and undefined`,`Maximum — goals should always be as large and ambitious as possible`,`Manual — goals must be tracked only on paper`], ans:0, exp:`"Measurable" means building in a concrete way to track progress and determine when the goal has actually been achieved — like "raise my chemistry grade to a B+" rather than just "do better in chemistry."` },
      { q:`Why does the "A" for "Achievable" matter when setting a goal?`, ch:[`Goals should always be set as unrealistically ambitious as possible`,`A goal that's realistically attainable, given your resources and constraints, is more likely to sustain motivation than one that feels impossible`,`Achievability has no bearing on whether a goal is effective`,`Only extremely easy goals should ever be set`], ans:1, exp:`A goal needs to be challenging enough to be meaningful, but realistically achievable given your actual resources, time, and circumstances — an impossible goal tends to undermine motivation rather than sustain it.` },
      { q:`Why is the "T" for "Time-bound" an important part of an effective goal?`, ch:[`Deadlines have no effect on motivation or follow-through`,`A specific deadline creates accountability and urgency, making a goal more likely to actually be pursued rather than indefinitely postponed`,`Goals should never include any timeframe`,`Time-bound goals are only relevant for professional settings`], ans:1, exp:`Attaching a specific deadline or timeframe creates a sense of urgency and accountability, which helps prevent a goal from being indefinitely put off with no clear endpoint.` },
      { q:`Which of these is the best example of a SMART goal for a student?`, ch:[`"I want to get better at math"`,`"Raise my algebra test average from a 75% to an 85% by completing two extra practice sets per week for the next six weeks"`,`"Be the best student in my class someday"`,`"Try to study more sometimes"`], ans:1, exp:`This goal is specific (raise algebra test average), measurable (75% to 85%), achievable, relevant to the student's actual coursework, and time-bound (over six weeks with a defined weekly action) — meeting all five SMART criteria.` },
    ],
  },
  {
    id:`fb35`, cat:`Behavioral & Social Sciences`, title:`Healthy Habits & Wellness 101`, diff:`Easy`,
    qs:[
      { q:`Why is regular physical activity generally recommended for both physical and mental well-being?`, ch:[`Exercise has no meaningful effect on mental health`,`Regular exercise is linked to improved mood, reduced stress, better sleep, and long-term physical health`,`Physical activity only benefits athletes, not typical students`,`Exercise should be avoided during periods of high academic stress`], ans:1, exp:`Research consistently links regular physical activity to improved mood, reduced anxiety and stress, better sleep quality, and long-term cardiovascular and metabolic health — benefits that extend well beyond physical fitness alone.` },
      { q:`Why is staying adequately hydrated throughout the day important for concentration and overall functioning?`, ch:[`Hydration has no effect on cognitive function`,`Even mild dehydration can negatively affect concentration, mood, and energy levels`,`Only athletes need to worry about hydration`,`Drinking water only matters immediately before physical exercise`], ans:1, exp:`Even relatively mild dehydration has been shown to negatively affect concentration, short-term memory, mood, and energy levels — making consistent hydration relevant well beyond just physical activity.` },
      { q:`Why might balancing academic responsibilities with social connection and downtime be important for long-term well-being?`, ch:[`Academic work should always take complete priority with zero time for anything else`,`Chronic overwork with no balance is linked to burnout, while social connection and rest support sustained motivation and mental health`,`Social connection has no bearing on academic or personal success`,`Downtime should be eliminated entirely to maximize productivity`], ans:1, exp:`Sustained, unbalanced overwork is strongly linked to burnout and declining performance over time, while adequate rest and social connection support the kind of consistent motivation and well-being needed for long-term success.` },
      { q:`Why is it considered healthier to build sustainable daily habits (like a consistent sleep schedule) rather than relying on occasional bursts of extreme effort?`, ch:[`Sustainable habits have no advantage over occasional extreme effort`,`Small, consistent habits are generally easier to maintain long-term and avoid the burnout risk that comes with unsustainable bursts of intense effort`,`Extreme, occasional effort is always more effective than steady habits`,`Habits have no bearing on long-term outcomes`], ans:1, exp:`Building small, sustainable daily habits (consistent sleep, regular study blocks, some physical activity) tends to be more sustainable and effective long-term than relying on occasional extreme pushes, which often lead to burnout and inconsistency.` },
      { q:`Why might it be valuable to occasionally check in with yourself about your own stress levels and overall well-being, rather than only focusing on academic output?`, ch:[`Self-check-ins have no practical value`,`Regularly noticing your own stress and well-being allows you to make adjustments before reaching a point of burnout or serious difficulty`,`Only academic performance should ever be monitored`,`Checking in on well-being is a sign of weakness that should be avoided`], ans:1, exp:`Periodically noticing your own stress levels, sleep, and overall well-being allows you to catch and address problems early — through adjusting your schedule, seeking support, or changing habits — rather than only noticing an issue once it's become serious.` },
    ],
  },
];
